import { test, expect } from '@playwright/test';

test.describe('Alert Dialog Interaction', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('https://your-website-url.com');
    await page.getByRole('button', { name: 'Open Alert Dialog' }).click();
  });

  test('should display the alert dialog', async ({ page }) => {
    const alertDialog = page.getByRole('dialog');
    await expect(alertDialog).toBeVisible();
  });

  test('should block interaction with the page behind the alert dialog', async ({ page }) => {
    const alertDialog = page.getByRole('dialog');
    await expect(alertDialog).toBeVisible();

    const backgroundElement = page.getByText('Background Element');
    await expect(backgroundElement).toBeDisabled(); // Assuming the background element is disabled when dialog is open
  });
});
